    "kernel_code": "1: \"\"\"Synthetic packed real FFT using a radix-2 complex transform.\"\"\"\n2: import torch\n3: import triton\n4: import triton.language as tl\n5: \n6: # Cosine table for the first quadrant of a 256-point transform.\n7: _COSINE = (\n8:     1.0, 0.9996988186962042, 0.9987954562051724, 0.9972904566786902,\n9:     0.9951847266721969, 0.99247953459871, 0.989176509964781, 0.9852776423889412,\n10:     0.9807852804032304, 0.9757021300385286, 0.970031253194544, 0.9637760657954398,\n11:     0.9569403357322088, 0.9495281805930367, 0.9415440651830208, 0.9329927988347388,\n12:     0.9238795325112867, 0.9142097557035307, 0.9039892931234433, 0.8932243011955153,\n13:     0.881921264348355, 0.8700869911087115, 0.8577286100002721, 0.8448535652497071,\n14:     0.8314696123025452, 0.8175848131515837, 0.8032075314806449, 0.7883464276266062,\n15:     0.773010453362737, 0.7572088465064846, 0.7409511253549591, 0.7242470829514669,\n16:     0.7071067811865476, 0.6895405447370669, 0.6715589548470184, 0.6531728429537768,\n17:     0.6343932841636455, 0.6152315905806268, 0.5956993044924334, 0.5758081914178453,\n18:     0.5555702330196022, 0.5349976198870973, 0.5141027441932218, 0.49289819222978404,\n19:     0.47139673682599764, 0.4496113296546066, 0.4275550934302821, 0.40524131400498986,\n20:     0.3826834323650898, 0.35989503653498817, 0.33688985339222005, 0.31368174039889146,\n21:     0.2902846772544624, 0.26671275747489837, 0.2429801799032639, 0.2191012401568698,\n22:     0.19509032201612828, 0.17096188876030122, 0.14673047445536175, 0.1224106751992162,\n23:     0.0980171403295606, 0.07356456359966743, 0.049067674327418015, 0.024541228522912288,\n24:     0.0,\n25: )\n26: \n27: \n28: @triton.jit\n29: def _reverse(index, LOG_M: tl.constexpr):\n30:     reversed_index = tl.full(index.shape, 0, tl.int32)\n31:     for bit in tl.static_range(LOG_M):\n32:         reversed_index = (reversed_index << 1) | ((index >> bit) & 1)\n33:     return reversed_index\n34: \n35: \n36: @triton.jit\n37: def _twiddle(TABLE, phase):\n38:     folded = tl.minimum(phase, 128 - phase)\n39:     cosine = tl.load(TABLE + folded)\n40:     cosine = tl.where(phase <= 64, cosine, -cosine)\n41:     sine = tl.load(TABLE + tl.abs(64 - phase))\n42:     return cosine, -sine\n43: \n44: \n45: @triton.jit\n46: def _realfft(X, TABLE, OUT, N: tl.constexpr, M: tl.constexpr, LOG_M: tl.constexpr):\n47:     row = tl.program_id(0)\n48:     k = tl.arange(0, M)\n49:     real = tl.load(X + row * N + 2 * k).to(tl.float64)\n50:     imag = tl.load(X + row * N + 2 * k + 1).to(tl.float64)\n51:     # Decimation in frequency leaves the complex transform in bit-reversed order.\n52:     for stage in tl.static_range(LOG_M):\n53:         width = M >> stage\n54:         half = width >> 1\n55:         left = k & ~half\n56:         right = k | half\n57:         ar = tl.gather(real, left, axis=0)\n58:         ai = tl.gather(imag, left, axis=0)\n59:         br = tl.gather(real, right, axis=0)\n60:         bi = tl.gather(imag, right, axis=0)\n61:         wr, wi = _twiddle(TABLE, (k & (half - 1)) * (256 // width))\n62:         dr = ar - br\n63:         di = ai - bi\n64:         lower = (k & half) == 0\n65:         real = tl.where(lower, ar + br, dr * wr - di * wi)\n66:         imag = tl.where(lower, ai + bi, dr * wi + di * wr)\n67:     address = _reverse(k, LOG_M)\n68:     partner = (-address) & (M - 1)\n69:     ar = tl.gather(real, address, axis=0)\n70:     ai = tl.gather(imag, address, axis=0)\n71:     br = tl.gather(real, partner, axis=0)\n72:     bi = tl.gather(imag, partner, axis=0)\n73:     # Reconstruct the real transform from the packed complex transform.\n74:     wr, wi = _twiddle(TABLE, k * (256 // N))\n75:     sr = ar + br\n76:     si = ai - bi\n77:     dr = ar - br\n78:     di = ai + bi\n79:     xr = 0.5 * (sr + (wr * di + wi * dr))\n80:     xi = 0.5 * (si - (wr * dr - wi * di))\n81:     tl.store(OUT + (row * (M + 1) + k) * 2, xr.to(tl.float32))\n82:     tl.store(OUT + (row * (M + 1) + k) * 2 + 1, xi.to(tl.float32))\n83:     tl.store(OUT + (row * (M + 1) + M + 0 * k) * 2, (ar - ai).to(tl.float32), mask=k == 0)\n84:     tl.store(OUT + (row * (M + 1) + M + 0 * k) * 2 + 1, 0.0, mask=k == 0)\n85: \n86: \n87: def validate_inputs(values, require_cuda=True):\n88:     \"\"\"Validate the public domain. Nonzero storage offsets are permitted.\"\"\"\n89:     def require(condition, message):\n90:         if not condition:\n91:             raise ValueError(message)\n92:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n93:     require(type(values) is torch.Tensor, \"ordinary torch.Tensor required\")\n94:     require(values.layout == torch.strided and values.is_contiguous(), \"contiguous strided input required\")\n95:     require(not values.requires_grad and not values.is_inference(), \"ordinary non-gradient input required\")\n96:     require(not values.is_neg() and not values.is_conj(), \"logical view flags are outside this domain\")\n97:     require(not require_cuda or values.is_cuda, \"CUDA input required by run\")\n98:     require(values.dtype == torch.float16, \"float16 input required\")\n99:     require(values.ndim == 2 and 1 <= values.shape[0] <= 256 and values.shape[1] in (64, 128, 256), \"shape must be [B,N], 1<=B<=256, N in {64,128,256}\")\n100:     require(bool(torch.isfinite(values).all()), \"all input values must be finite\")\n101:     return {\"valid\": True, \"batch\": values.shape[0], \"width\": values.shape[1]}\n102: \n103: \n104: def run(values):\n105:     \"\"\"Return real and imaginary components in a fresh FP32 tensor.\"\"\"\n106:     validate_inputs(values)\n107:     batch, n = values.shape\n108:     m = n // 2\n109:     with torch.cuda.device(values.device):\n110:         table = torch.tensor(_COSINE, dtype=torch.float64, device=values.device)\n111:         output = torch.empty((batch, m + 1, 2), dtype=torch.float32, device=values.device)\n112:         _realfft[(batch,)](values, table, output, N=n, M=m, LOG_M=m.bit_length() - 1,\n113:                           num_warps=4, enable_fp_fusion=False)\n114:     return output\n115: \n116: \n117: def reference(values):\n118:     \"\"\"A separate library transform in complex128, returned as FP64 components.\"\"\"\n119:     validate_inputs(values, require_cuda=False)\n120:     result = torch.fft.rfft(values.to(torch.float64), dim=1, norm=\"backward\")\n121:     return torch.stack((result.real, result.imag), dim=-1)\n122: \n123: \n124: def make_inputs(device=\"cuda\", batch=7, width=128, seed=0):\n125:     \"\"\"Examples only; the contract includes every finite FP16 input.\"\"\"\n126:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n127:     values = torch.randn((batch, width), generator=generator).to(torch.float16)\n128:     return (values.to(device),)",
    "passed": "unknown",
    "problem_text": "Compute the unnormalized forward discrete Fourier transform of each real input row. For every row b and frequency k from 0 through N/2, the exact mathematical result is X[b,k] = sum(values[b,j] * exp(-2*pi*i*j*k/N), j=0..N-1). Return its real and imaginary components in this order, as a fresh contiguous torch.float32 tensor with shape [B,N/2+1,2] on the input device. Frequencies must be in their natural increasing order. There is no normalization factor.\n\nThe input is one ordinary contiguous strided CUDA torch.float16 tensor values with shape [B,N], where 1<=B<=256 and N is 64, 128, or 256. Every finite FP16 value is legal, including signed zeros, subnormal values, and both finite extremes. There is no restriction on the input distribution or frequency content. Nonzero storage offsets are legal. Inputs have no gradient, inference, conjugate, or negative-view flags. Calls use ordinary execution mode.\n\nFor each output component, require abs(actual-exact) <= 1e-4 + 1e-6*abs(exact). Both constants are exact decimal values. A nonfinite output is incorrect. The exact result above defines correctness; the supplied FP64 library reference is a comparison implementation, not a different mathematical specification. run must preserve the entire input storage and return separate output storage. The guarantee covers every legal input under the fixed NVIDIA T4, PyTorch 2.8.0 and Triton 3.4.0 environment. Performance is not part of this task.\n",
